
.card {
  width: 100%;
  max-width: 520px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 2px solid var(--c-brass);
  border-radius: 12px;
  overflow: hidden;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 12px;
  box-shadow: 0 3px 12px rgba(60, 45, 30, 0.12);
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 10px 14px;
  background: linear-gradient(135deg, var(--c-brass-deep), var(--c-copper));
}

.title {
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 2px;
}

.subtitle {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
}

.body {
  padding: 10px 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.section-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--c-brass-deep);
}

.track {
  position: relative;
  height: 18px;
  border-radius: 9px;
  background: #fff;
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-lust), var(--c-lust-deep));
  transition: width 0.5s ease;
}

.pct {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 10px;
  font-weight: 700;
  color: var(--c-text);
}

.note {
  font-size: 11px;
  color: var(--c-text-muted);
}

.countdown {
  font-size: 20px;
  font-weight: 700;
  color: var(--c-brass-deep);
  letter-spacing: 1px;
  font-variant-numeric: tabular-nums;
}

.row {
  flex-direction: row;
  gap: 12px;
}

.mini {
  flex: 1;
  background: #fff;
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 6px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.mini-label {
  font-size: 10px;
  color: var(--c-text-muted);
}

.mini-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--c-text);
}
